// Pega o parâmetro "dica" da URL
const parametros = new URLSearchParams(window.location.search);
const nomeDica = parametros.get("dica");
const nivel = parametros.get("nivel");
document.getElementById("btn-voltar").href =
    `./dicas_cards.html?nivel=${nivel}`;

// Procura a dica correspondente
const dicaSelecionada = dicas[nomeDica];

// Preenche a página
if (dicaSelecionada) {
    document.getElementById("titulo-dica").textContent = dicaSelecionada.titulo;
    document.getElementById("texto-dica").textContent = dicaSelecionada.texto;
} else {
    console.warn(`Dica "${nomeDica}" não encontrada.`);
}

